SELECT lr.*, l.name AS lab_name, u.real_name AS user_name FROM lab_reservation lr LEFT JOIN lab_room l ON lr.lab_id = l.id LEFT JOIN `user` u ON lr.user_id = u.id
AND lr.status = #{status} AND lr.user_id = #{userId}
ORDER BY lr.create_time DESC

SELECT COUNT(*) FROM lab_reservation
WHERE lab_id = #{labId} AND reserve_date = #{reserveDate}
AND time_slot = #{timeSlot} AND status IN (0, 1)
AND id != #{excludeId}

mapper.update:
UPDATE lab_reservation
status = #{status}, audit_user_id = #{auditUserId}, audit_time = #{auditTime},
WHERE id = #{id}
